def transform(grid):
    """Turn the empty cells following the rightmost colored cell in each
    marked row into the continuation color 1."""
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        marked = [c for c, value in enumerate(row) if value != bg]
        if marked:
            for c in range(max(marked) + 1, len(row)):
                if row[c] == bg:
                    out[r][c] = 1
    return out

