def transform(grid):
    """Replace background gaps and tails to the right of foreground with 1."""
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        positions = [c for c, value in enumerate(row) if value != bg]
        if positions:
            # Preserve original foreground; mark every background cell between
            # the leftmost foreground and the right boundary as continuation.
            for c in range(min(positions), len(row)):
                if row[c] == bg:
                out[r][c] = 1
    return out

